<?php
require_once __DIR__.'/../includes/helpers.php'; require_role('admin'); $title=t('nav.admin_reports');
if($_SERVER['REQUEST_METHOD']==='POST'){
  verify_csrf(); $rid=(int)($_POST['report_id']??0); $aid=(int)($_POST['archaeologist_id']??0);
  if($rid&&$aid){ query('INSERT INTO ae_report_assignments(report_id,archaeologist_id,assigned_by,status,notes) VALUES(?,?,?,"assigned",?)',[$rid,$aid,current_user()['id'],trim($_POST['notes']??'')]); query("UPDATE ae_incident_reports SET status='assigned' WHERE id=?",[$rid]); flash('success',localized('تم إسناد البلاغ للعالم الأثري.','The report has been assigned to the archaeologist.')); }
  redirect('admin/reports.php');
}
$reports=fetch_all('SELECT r.*,s.name site_name,s.city,u.name user_name,ra.archaeologist_id,au.name archaeologist_name FROM ae_incident_reports r JOIN ae_heritage_sites s ON s.id=r.site_id LEFT JOIN ae_users u ON u.id=r.user_id LEFT JOIN ae_report_assignments ra ON ra.report_id=r.id AND ra.status="assigned" LEFT JOIN ae_users au ON au.id=ra.archaeologist_id ORDER BY r.id DESC');
$arch=fetch_all("SELECT id,name FROM ae_users WHERE role='archaeologist' AND status='active'"); include __DIR__.'/../includes/header.php';
?>
<section class="page-hero"><span class="eyebrow"><?= h(localized('دورة البلاغ','Incident Workflow')) ?></span><h1><?= h(t('nav.admin_reports')) ?></h1><p><?= h(localized('راجع البلاغات الجديدة، ثم أسند المهمة إلى عالم أثري مع ملاحظات الزيارة الميدانية.','Review new reports, then assign each task to an archaeologist with field-visit notes.')) ?></p></section>
<div class="cards"><div class="card stat-line"><div><div class="stat-num"><?= count(array_filter($reports,fn($r)=>$r['status']==='new')) ?></div><b><?= h(status_label('new')) ?></b></div><div class="icon-box"><i class="ti ti-alert-circle"></i></div></div><div class="card stat-line"><div><div class="stat-num"><?= count(array_filter($reports,fn($r)=>$r['status']==='assigned')) ?></div><b><?= h(status_label('assigned')) ?></b></div><div class="icon-box"><i class="ti ti-route"></i></div></div><div class="card stat-line"><div><div class="stat-num"><?= count(array_filter($reports,fn($r)=>$r['status']==='under_review')) ?></div><b><?= h(status_label('under_review')) ?></b></div><div class="icon-box"><i class="ti ti-clipboard-search"></i></div></div><div class="card stat-line"><div><div class="stat-num"><?= count(array_filter($reports,fn($r)=>$r['status']==='closed')) ?></div><b><?= h(status_label('closed')) ?></b></div><div class="icon-box"><i class="ti ti-circle-check"></i></div></div></div>
<div class="table-card"><div class="table-responsive"><table class="table"><thead><tr><th><?= h(localized('البلاغ','Report')) ?></th><th><?= h(t('reports.site')) ?></th><th><?= h(localized('المرسل','Submitted By')) ?></th><th><?= h(localized('الأولوية','Priority')) ?></th><th><?= h(t('common.status')) ?></th><th><?= h(localized('المتابعة','Follow-up')) ?></th></tr></thead><tbody><?php foreach($reports as $r): ?><tr><td><b><?= h($r['title']) ?></b><br><span class="mini"><?= h(excerpt($r['description'],110)) ?></span></td><td><?= h($r['site_name']) ?><br><span class="mini"><?= h($r['city']) ?></span></td><td><?= h($r['user_name']??localized('غير محدد','Not specified')) ?></td><td><span class="badge badge-<?= $r['priority']==='high'?'danger':($r['priority']==='low'?'success':'warning') ?>"><?= h(priority_label($r['priority'])) ?></span></td><td><span class="badge badge-neutral"><?= h(status_label($r['status'])) ?></span></td><td><?php if($r['status']==='new'): ?><button class="btn btn-primary" type="button" data-assign-report data-report-id="<?= (int)$r['id'] ?>" data-report-title="<?= h($r['title']) ?>"><i class="ti ti-user-check"></i><?= h(localized('إسناد المهمة','Assign Task')) ?></button><?php elseif($r['archaeologist_name']): ?><span class="badge badge-success"><i class="ti ti-user"></i><?= h($r['archaeologist_name']) ?></span><?php else: ?>—<?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div>
<template id="assignmentTemplate"><div class="modal-head"><span class="eyebrow"><?= h(localized('إسناد ميداني','Field Assignment')) ?></span><h2 data-assignment-title><?= h(localized('إسناد البلاغ','Assign Report')) ?></h2><p><?= h(localized('اختر العالم الأثري واكتب تعليمات واضحة للزيارة.','Choose an archaeologist and provide clear field-visit instructions.')) ?></p></div><form method="post"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="report_id" data-report-id-input><div class="form-grid"><div class="form-group full"><label class="form-label"><?= h(t('role.archaeologist')) ?></label><select class="form-select" name="archaeologist_id" required><?php foreach($arch as $a): ?><option value="<?= (int)$a['id'] ?>"><?= h($a['name']) ?></option><?php endforeach; ?></select></div><div class="form-group full"><label class="form-label"><?= h(localized('ملاحظات الزيارة','Visit Notes')) ?></label><textarea name="notes" placeholder="<?= h(localized('المطلوب فحصه، الأولوية، الصور المطلوبة...','What to inspect, priority, required photos...')) ?>"></textarea></div></div><div class="actions"><button class="btn btn-primary"><i class="ti ti-send"></i><?= h(localized('إسناد البلاغ','Assign Report')) ?></button><button class="btn btn-light" type="button" data-modal-close><?= h(t('common.cancel')) ?></button></div></form></template>
<script>document.addEventListener('DOMContentLoaded',()=>{document.querySelectorAll('[data-assign-report]').forEach(b=>b.addEventListener('click',()=>{const t=document.querySelector('#assignmentTemplate');if(!t)return;AtharModal.open(t.innerHTML);const c=document.querySelector('#appModalContent');c.querySelector('[data-report-id-input]').value=b.dataset.reportId;c.querySelector('[data-assignment-title]').textContent=b.dataset.reportTitle;}));});</script>
<?php include __DIR__.'/../includes/footer.php'; ?>
